

var renderClass = "jp.ngt.rtm.render.MachinePartsRenderer";



importPackage(Packages.org.lwjgl.opengl);
importPackage(Packages.jp.ngt.rtm.render);



function init(par1, par2) {

	Main = renderer.registerParts(new Parts("Main"));
	Switch = renderer.registerParts(new Parts("On"));

}



function render(entity, pass, par3) {

	GL11.glPushMatrix();

	if(pass == 0) {

		Main.render(renderer);

		GL11.glPushMatrix();

			var state = renderer.getMovingCount(entity);

			if(state == 0) {

				Switch.render(renderer);

			} else {

				GL11.glTranslatef(0, 0, -0.011)
				Switch.render(renderer);

			}

		GL11.glPopMatrix();

	}

	GL11.glPopMatrix();

}